import { computed, defineComponent, h, ref, type PropType } from 'vue';
import {
	addMonths,
	calendarStyleKeys,
	getCalendarDayModifiers,
	getCalendarFirstSelectedDate,
	getMonthCaption,
	getMonthGrid,
	getWeekdayLabels,
	selectCalendarDay,
	startOfMonth,
} from '../lib/core';
import type { CalendarDayModifiers, CalendarDisabledMatcher, CalendarMode, CalendarSelection } from '../lib/core';
import styles from './calendar.module.scss';

/**
 * 渲染左 / 右方向箭头图标
 */
function renderChevron(flipRight: boolean) {
	return h(
		'svg',
		{
			class: styles[calendarStyleKeys.icon],
			xmlns: 'http://www.w3.org/2000/svg',
			width: '24',
			height: '24',
			viewBox: '0 0 24 24',
			fill: 'none',
			stroke: 'currentColor',
			'stroke-width': '2',
			'stroke-linecap': 'round',
			'stroke-linejoin': 'round',
			'aria-hidden': 'true',
		},
		[h('path', { d: flipRight ? 'm9 18 6-6-6-6' : 'm15 18-6-6 6-6' })],
	);
}

/**
 * 单个日期按钮（独立导出，供自定义网格使用）
 */
export const CalendarDayButton = defineComponent({
	name: 'CalendarDayButton',
	props: {
		date: { type: Date, required: true },
		modifiers: { type: Object as PropType<CalendarDayModifiers>, required: true },
	},
	emits: ['click'],
	setup(props, { attrs, emit, slots }) {
		return () => {
			const modifiers = props.modifiers;
			const data: Record<string, string> = {
				'data-day': props.date.toLocaleDateString(),
				'data-selected': String(modifiers.selected),
				'data-selected-single': String(modifiers.selected && !modifiers.rangeStart && !modifiers.rangeEnd && !modifiers.rangeMiddle),
				'data-range-start': String(modifiers.rangeStart),
				'data-range-end': String(modifiers.rangeEnd),
				'data-range-middle': String(modifiers.rangeMiddle),
				'data-outside': String(modifiers.outside),
				'data-disabled': String(modifiers.disabled),
				'data-today': String(modifiers.today),
				'aria-disabled': String(modifiers.disabled),
			};

			return h(
				'button',
				{
					...attrs,
					...data,
					type: 'button',
					disabled: modifiers.disabled,
					class: [styles[calendarStyleKeys.dayButton], attrs.class],
					onClick: () => emit('click'),
				},
				slots.default?.() ?? [props.date.getDate()],
			);
		};
	},
});

/**
 * Calendar 日历组件（单选 / 多选 / 范围选择）
 */
export const Calendar = defineComponent({
	name: 'Calendar',
	props: {
		mode: {
			type: String as PropType<CalendarMode>,
			default: 'single',
		},
		selected: { type: [Date, Array, Object] as PropType<CalendarSelection>, default: undefined },
		defaultSelected: { type: [Date, Array, Object] as PropType<CalendarSelection>, default: undefined },
		defaultMonth: { type: Date, default: undefined },
		showOutsideDays: { type: Boolean, default: true },
		disabled: { type: Function as PropType<CalendarDisabledMatcher>, default: undefined },
	},
	emits: ['select', 'update:selected'],
	setup(props, { emit, attrs }) {
		const internalSelected = ref<CalendarSelection>(props.defaultSelected);
		const currentSelected = computed<CalendarSelection>(() => (props.selected !== undefined ? props.selected : internalSelected.value));

		function resolveInitialMonth(): Date {
			if (props.defaultMonth) {
				return startOfMonth(props.defaultMonth);
			}
			const firstSelected = getCalendarFirstSelectedDate(props.defaultSelected);
			return firstSelected ? startOfMonth(firstSelected) : startOfMonth(new Date());
		}

		const month = ref<Date>(resolveInitialMonth());

		function handleSelect(day: Date) {
			if (props.disabled?.(day)) {
				return;
			}
			const next = selectCalendarDay(props.mode, currentSelected.value, day);
			if (props.selected === undefined) {
				internalSelected.value = next;
			}
			emit('select', next);
			emit('update:selected', next);
		}

		return () => {
			const grid = getMonthGrid(month.value, props.showOutsideDays);
			const weekdays = getWeekdayLabels();
			const classes = [styles[calendarStyleKeys.root], attrs.class];

			return h('div', { ...attrs, class: classes, 'data-slot': 'calendar', 'data-mode': props.mode }, [
				h('div', { class: styles[calendarStyleKeys.header] }, [
					h('nav', { class: styles[calendarStyleKeys.nav] }, [
						h(
							'button',
							{
								type: 'button',
								'aria-label': '上个月',
								class: [styles[calendarStyleKeys.navButton], styles[calendarStyleKeys.navPrev]],
								onClick: () => (month.value = addMonths(month.value, -1)),
							},
							renderChevron(false),
						),
						h(
							'button',
							{
								type: 'button',
								'aria-label': '下个月',
								class: [styles[calendarStyleKeys.navButton], styles[calendarStyleKeys.navNext]],
								onClick: () => (month.value = addMonths(month.value, 1)),
							},
							renderChevron(true),
						),
					]),
					h('div', { class: styles[calendarStyleKeys.monthCaption] }, getMonthCaption(month.value)),
				]),
				h(
					'div',
					{ class: styles[calendarStyleKeys.weekdays] },
					weekdays.map((label) => h('div', { class: styles[calendarStyleKeys.weekday] }, label)),
				),
				h('div', { class: styles[calendarStyleKeys.weeks], role: 'grid' }, [
					grid.map((week, weekIndex) =>
						h('div', { role: 'row', class: styles[calendarStyleKeys.week] }, [
							week.map((day, dayIndex) => {
								if (!day) {
									return h('div', { key: `${weekIndex}-${dayIndex}`, class: styles[calendarStyleKeys.day] });
								}
								const modifiers = getCalendarDayModifiers(day, month.value, currentSelected.value, props.showOutsideDays, props.disabled);
								return h(
									'div',
									{ key: `${weekIndex}-${dayIndex}`, role: 'gridcell', 'aria-selected': String(modifiers.selected), class: styles[calendarStyleKeys.day] },
									[
										h(CalendarDayButton, {
											date: day,
											modifiers,
											onClick: () => handleSelect(day),
										}),
									],
								);
							}),
						]),
					),
				]),
			]);
		};
	},
});

export default Calendar;

@use '../../../styles/variables/colors' as *;

// 日历根容器
.root {
	width: fit-content;
	padding: var(--tile-calendar-padding, $spacing-3);
	background-color: var(--tile-calendar-background, $background);
	border-radius: var(--tile-calendar-radius, $radius-md);
	border: var(--tile-calendar-border, 1px solid $border);
	font-variant-numeric: var(--tile-calendar-numerals, inherit);
}

// 头部（导航 + 月份标题）
.header {
	position: relative;
	height: var(--tile-calendar-header-height, auto);
	display: flex;
	align-items: center;
}

// 上 / 下月导航
.nav {
	display: flex;
	align-items: center;
	justify-content: space-between;
	width: 100%;
	gap: $spacing-1;
}

.navButton {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: var(--tile-calendar-nav-size, 2rem);
	height: var(--tile-calendar-nav-size, 2rem);
	padding: 0;
	border: none;
	border-radius: var(--tile-calendar-day-radius, $radius);
	box-shadow: var(--tile-calendar-nav-shadow, none);
	background-color: transparent;
	color: $foreground;
	cursor: pointer;
	outline: none;
	transition: background-color $transition-fast;

	&:hover:not(:disabled) {
		background-color: var(--tile-calendar-hover-background, $accent);
		color: $accent-foreground;
	}

	&:focus-visible {
		box-shadow: var(--tile-calendar-focus-shadow, 0 0 0 2px $background, 0 0 0 4px $ring);
	}

	&:disabled {
		opacity: 0.5;
		pointer-events: none;
	}

	.icon {
		width: 1rem;
		height: 1rem;
		pointer-events: none;
	}
}

// 月份标题
.monthCaption {
	position: absolute;
	inset-inline: 2rem;
	display: flex;
	align-items: center;
	justify-content: center;
	font-size: $text-sm;
	font-weight: var(--tile-calendar-caption-weight, $font-medium);
	user-select: none;
	pointer-events: none;
}

// 星期表头
.weekdays {
	display: flex;
	width: 100%;
	margin-top: var(--tile-calendar-weekdays-margin, $spacing-2);
}

.weekday {
	flex: 1;
	border-radius: $radius;
	font-size: var(--tile-calendar-weekday-size, 0.8rem);
	font-weight: var(--tile-calendar-weekday-weight, $font-normal);
	color: $muted-foreground;
	text-align: center;
	padding-block: var(--tile-calendar-weekday-padding, $spacing-1);
	user-select: none;
}

// 日期网格
.weeks {
	display: flex;
	flex-direction: column;
	gap: var(--tile-calendar-weeks-gap, $spacing-1);
	margin-top: var(--tile-calendar-weeks-margin, $spacing-1);
}

.week {
	display: flex;
	width: 100%;
}

// 日期单元格
.day {
	flex: 1;
	padding: var(--tile-calendar-cell-padding, 0);
	display: flex;
	align-items: center;
	justify-content: center;
}

.dayButton {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 2rem;
	height: 2rem;
	min-width: 2rem;
	padding: 0;
	border: none;
	border-radius: var(--tile-calendar-day-radius, $radius);
	background-color: transparent;
	color: $foreground;
	font-size: var(--tile-calendar-day-size, $text-sm);
	font-weight: $font-normal;
	line-height: 1;
	text-align: center;
	cursor: pointer;
	outline: none;
	transition:
		background-color $transition-fast,
		color $transition-fast;
	user-select: none;

	&:hover:not(:disabled):not([data-selected='true']) {
		background-color: var(--tile-calendar-hover-background, $accent);
		color: $accent-foreground;
	}

	&:focus-visible {
		box-shadow: var(--tile-calendar-focus-shadow, 0 0 0 2px $background, 0 0 0 4px $ring);
	}

	// 今天
	&[data-today='true'] {
		background-color: var(--tile-calendar-today-background, $accent);
		color: var(--tile-calendar-today-color, $accent-foreground);
		font-weight: var(--tile-calendar-today-weight, $font-normal);

		&[data-selected='true'] {
			background-color: var(--tile-calendar-selected-background, $primary);
			color: var(--tile-calendar-selected-color, $primary-foreground);
		}
	}

	// 相邻月份的天
	&[data-outside='true'] {
		color: $muted-foreground;
		opacity: var(--tile-calendar-outside-opacity, 1);
	}

	// 禁用
	&[data-disabled='true'] {
		color: $muted-foreground;
		opacity: var(--tile-calendar-disabled-opacity, 0.5);
		cursor: not-allowed;
		pointer-events: none;
	}

	// 单选选中态
	&[data-selected-single='true'] {
		background-color: var(--tile-calendar-selected-background, $primary);
		color: var(--tile-calendar-selected-color, $primary-foreground);
	}

	// 范围起点
	&[data-range-start='true'] {
		background-color: var(--tile-calendar-selected-background, $primary);
		color: var(--tile-calendar-selected-color, $primary-foreground);
		border-radius: var(--tile-calendar-day-radius, $radius);
		border-end-end-radius: 0;
		border-start-end-radius: 0;
	}

	// 范围终点
	&[data-range-end='true'] {
		background-color: var(--tile-calendar-selected-background, $primary);
		color: var(--tile-calendar-selected-color, $primary-foreground);
		border-radius: var(--tile-calendar-day-radius, $radius);
		border-start-start-radius: 0;
		border-end-start-radius: 0;
	}

	// 范围中间
	&[data-range-middle='true'] {
		background-color: var(--tile-calendar-range-background, $accent);
		color: var(--tile-calendar-range-color, $accent-foreground);
		border-radius: 0;
	}
}
